import urllib.request, re
# crawl pages or links
visited = set()
to_visit = {'http://commons.local/'}
while to_visit:
    url = to_visit.pop()
    if url in visited: continue
    visited.add(url)
    try:
        html = urllib.request.urlopen(url).read().decode('utf-8', errors='ignore')
        # find links
        links = re.findall(r'href=[\'\"]([^\'\"]+)[\'\"]', html)
        for link in links:
            if link.startswith('/'):
                full = 'http://commons.local' + link
                if full not in visited:
                    to_visit.add(full)
    except Exception as e:
        pass
print('Visited URLs:', len(visited))
for u in sorted(visited):
    print(u)
""}

